const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeErie = ee.Geometry.Polygon(
    [
      [-83.5, 41.3],
      [-83.5, 43.0],
      [-78.5, 43.0],
      [-78.5, 41.3],
      [-83.5, 41.3]
    ],
    null,
    false
  );

  const date1 = '2014-01-09';
  const date1End = '2014-01-10'; // Single day
  const date2 = '2014-01-14';
  const date2End = '2014-01-15'; // Single day

  // Landsat 8 Collection
  const L8_COLLECTION = 'LANDSAT/LC08/C02/T1_L2';

  // Function to mask clouds and detect ice
  function processImage(image) {
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const qaPixel = image.select('QA_PIXEL');
    const cloudShadowBitMask = 1 << 3;
    const cloudsBitMask = 1 << 5;
    const cirrusBitMask = 1 << 8; // Bit 8 is cirrus

    // Both flags should be set to 0, indicating clear conditions.
    const mask = qaPixel.bitwiseAnd(cloudShadowBitMask).eq(0)
      .and(qaPixel.bitwiseAnd(cloudsBitMask).eq(0))
      .and(qaPixel.bitwiseAnd(cirrusBitMask).eq(0));

    const maskedImage = image.updateMask(mask).select(['SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B6', 'SR_B7']);

    // Scale reflectance to 0-1
    const scaledImage = maskedImage.multiply(0.0000275).add(-0.2).clamp(0, 1);

    // Ice detection using a combination of bands:
    // Ice is typically very bright in visible bands and can be distinguished from water.
    // Water absorbs more in NIR and SWIR.
    // A simple threshold on blue band (B2) is often effective for bright ice over dark water.
    // Or, use NDWI where water is positive, ice is near zero or slightly negative.
    // For ice, we want to detect bright, non-water features.
    // A threshold on the Blue band (B2) could work, or a modified NDWI to detect non-water bright pixels.
    // Let's use a threshold on SR_B2 for brightness (ice is typically very bright)
    // and SR_B6 (SWIR1) to help distinguish from other bright features/clouds.
    // Ice reflects highly in visible, lower in SWIR compared to snow, but higher than water.
    // A simple test: bright in B2, and not extremely low in B6 (to exclude open water).
    const blue = scaledImage.select('SR_B2');
    const swir1 = scaledImage.select('SR_B6');

    // Thresholds might need adjustment
    const ice = blue.gt(0.2).and(swir1.gt(0.05)); // Bright in blue and not too dark in SWIR1

    return image.addBands(ice.rename('ice_mask'));
  }

  // 2. Data Acquisition & Check
  let col1 = ee.ImageCollection(L8_COLLECTION)
    .filterBounds(lakeErie)
    .filterDate(date1, date1End)
    .map(processImage);

  let col2 = ee.ImageCollection(L8_COLLECTION)
    .filterBounds(lakeErie)
    .filterDate(date2, date2End)
    .map(processImage);

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  if (size1 === 0) {
    console.log(`No images found for ${date1}. Trying a wider date range.`);
    // Try widening the date range for col1
    col1 = ee.ImageCollection(L8_COLLECTION)
      .filterBounds(lakeErie)
      .filterDate(ee.Date(date1).advance(-2, 'day'), ee.Date(date1End).advance(2, 'day'))
      .map(processImage);
    const widerSize1 = await col1.size().getInfo();
    if (widerSize1 === 0) {
      console.log(`No images found for ${date1} even with wider range.`);
      console.log("C1");
      return;
    } else {
      console.log(`Found ${widerSize1} images for ${date1} with wider range.`);
    }
  }

  if (size2 === 0) {
    console.log(`No images found for ${date2}. Trying a wider date range.`);
    // Try widening the date range for col2
    col2 = ee.ImageCollection(L8_COLLECTION)
      .filterBounds(lakeErie)
      .filterDate(ee.Date(date2).advance(-2, 'day'), ee.Date(date2End).advance(2, 'day'))
      .map(processImage);
    const widerSize2 = await col2.size().getInfo();
    if (widerSize2 === 0) {
      console.log(`No images found for ${date2} even with wider range.`);
      console.log("C1");
      return;
    } else {
      console.log(`Found ${widerSize2} images for ${date2} with wider range.`);
    }
  }

  // Get the least cloudy image for each period
  let img1, img2;

  if (size1 > 0) {
    img1 = col1.mosaic().clip(lakeErie);
    const cloudCover1 = ee.Image(col1.sort('CLOUD_COVER').first()).get('CLOUD_COVER').getInfo();
    console.log(`2014-01-09 Image Cloud Cover: ${cloudCover1 !== null ? cloudCover1.toFixed(2) : 'N/A'}%`);
  } else {
    // If we only found images after widening the range for col1
    img1 = col1.sort('CLOUD_COVER').first().clip(lakeErie);
    const cloudCover1 = img1.get('CLOUD_COVER').getInfo();
    console.log(`2014-01-09 (Wider Range) Image Cloud Cover: ${cloudCover1 !== null ? cloudCover1.toFixed(2) : 'N/A'}%`);
  }

  if (size2 > 0) {
    img2 = col2.mosaic().clip(lakeErie);
    const cloudCover2 = ee.Image(col2.sort('CLOUD_COVER').first()).get('CLOUD_COVER').getInfo();
    console.log(`2014-01-14 Image Cloud Cover: ${cloudCover2 !== null ? cloudCover2.toFixed(2) : 'N/A'}%`);
  } else {
    // If we only found images after widening the range for col2
    img2 = col2.sort('CLOUD_COVER').first().clip(lakeErie);
    const cloudCover2 = img2.get('CLOUD_COVER').getInfo();
    console.log(`2014-01-14 (Wider Range) Image Cloud Cover: ${cloudCover2 !== null ? cloudCover2.toFixed(2) : 'N/A'}%`);
  }

  // Check if img1 or img2 are undefined due to empty collections even after widening
  if (!img1 || !img2) {
    console.log("C1");
    return;
  }

  // 3. Processing & Calculation
  const scale = 300; // Landsat resolution is 30m, use a larger scale to avoid maxPixels issues

  const iceMask1 = img1.select('ice_mask');
  const iceMask2 = img2.select('ice_mask');

  const iceCount1 = iceMask1.reduceRegion({
    reducer: ee.Reducer.sum(), // Sum of 1s will give pixel count
    geometry: lakeErie,
    scale: scale,
    maxPixels: 1e9,
    crs: 'EPSG:4326' // Explicitly set CRS to avoid projection issues
  }).get('ice_mask');

  const iceCount2 = iceMask2.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeErie,
    scale: scale,
    maxPixels: 1e9,
    crs: 'EPSG:4326'
  }).get('ice_mask');

  let val1 = await iceCount1.getInfo();
  let val2 = await iceCount2.getInfo();

  // Convert pixel counts to area (square kilometers)
  const pixelAreaSqKm = (scale * scale) / 1e6;

  let area1_sqkm = val1 !== null ? val1 * pixelAreaSqKm : null;
  let area2_sqkm = val2 !== null ? val2 * pixelAreaSqKm : null;

  // 5. Validation & Final Answer
  if (val1 === null || val2 === null) {
    console.log("C3"); // Calculation failed, result is None/NaN
    return;
  }

  if (area1_sqkm === 0 && area2_sqkm === 0) {
    console.log("No valid pixels for ice detected on either date after processing.");
    // This could mean no ice or very heavy clouds that mask everything, or our ice detection is too strict.
    // Given the question, it's more likely "no ice detected" rather than "no valid pixels" unless mask is too aggressive.
    // If this is due to excessive cloud masking, it's C2. If valid pixels exist but no ice, then it's A/B based on 0s.
    // For now, assume it's valid zero if pixels exist in the image overall.
    // To distinguish C2 properly, we would need to check overall valid pixels before ice mask.
    // Let's assume if val1/val2 is 0 here, it means no ice was detected rather than entire lake masked.
  }

  console.log(`Ice cover on 2014-01-09: ${area1_sqkm !== null ? area1_sqkm.toFixed(2) : 'N/A'} sq km`);
  console.log(`Ice cover on 2014-01-14: ${area2_sqkm !== null ? area2_sqkm.toFixed(2) : 'N/A'} sq km`);

  if (area2_sqkm < area1_sqkm) {
    console.log("A"); // Yes, ice cover decreased
  } else {
    console.log("B"); // No, ice cover did not decrease
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
